# Super Mario Bros. (NROM-256): names for the recompiler.
#
# Each line is "kind $address name [length] [: type] ; description".
# Routines are entry points, tables are data inside PRG ROM (including the
# inline jump tables that follow calls to the dispatcher), and var/io name
# RAM and hardware registers; a length makes an array. A type names the
# values of a variable: "enum NAME VALUE=N ..." or, for bits that combine,
# "flags NAME BIT=N ...", which the C writes as NAME_VALUE. The names are
# this project's own.
#
# The dump the map was written for: SHA-256 of PRG then CHR ROM, without the
# iNES header (so it matches headered and raw dumps), and their sizes. It is
# the dump tests/golden/warpless.trace was recorded with.
rom fcb6a0ef3a20c19b356005fbb21dc8009563b1cb5a9aaebc8e9386b4a8c5912e 32768 8192 ; Super Mario Bros. (NES)

# Types of variables
enum game_mode title=0 playing=1 victory=2 game_over=3
flags button a=$80 b=$40 select=$20 start=$10 up=$08 down=$04 left=$02 right=$01 ; as read from a joypad
flags direction right=$01 left=$02
enum player_state on_ground=0 jumping=1 falling=2 climbing=3 ; jumping also while swimming up
enum power small=0 big=1 fiery=2
enum area_kind water=0 ground=1 underground=2 castle=3

# Records: arrays of RAM indexed alike, as one structure's fields in the C
# (enemy(x).kind for enemy_kind(x)). The bytes stay where they are.
record enemy enemy_active enemy_kind enemy_state enemy_dir enemy_x_speed enemy_page enemy_x enemy_y_speed enemy_y_page enemy_y enemy_sprite_attr enemy_x_force enemy_y_fraction enemy_y_force enemy_collision enemy_box_kind enemy_sprite_slot enemy_frame_timer enemy_interval_timer ; an enemy slot (0-4, 5 for powerups and the flag)
record obj obj_state obj_dir obj_x_speed obj_page obj_x obj_y_speed obj_y_page obj_y obj_screen_x obj_screen_y obj_sprite_attr obj_offscreen obj_x_force obj_y_fraction obj_y_force obj_collision obj_box_kind ; an object slot: the player, enemies, fireballs, blocks, misc objects and bubbles in turn
record fireball fireball_state fireball_bouncing fireball_x_speed fireball_page fireball_x fireball_y_speed fireball_y_page fireball_y fireball_box_kind fireball_sprite_slot ; a fireball slot
record block block_state block_x_speed block_page block_x block_y_speed block_y_page block_y block_screen_x block_screen_y block_offscreen block_origin_y block_buffer_low block_metatile block_page2 block_replace block_origin_x block_y_force block_sprite_slot ; a bumped block slot (brick chunks use two more)
record misc misc_state misc_x_speed misc_page misc_x misc_y_speed misc_y_page misc_y misc_box_kind misc_contact misc_sprite_slot ; a slot for hammers and jumping coins
record bubble bubble_page bubble_x bubble_y_page bubble_y bubble_y_fraction bubble_sprite_slot ; an air bubble slot
record popup popup_kind popup_x popup_y popup_timer ; a floating score
record cannon cannon_page cannon_x cannon_y cannon_timer ; a cannon that fires bullets
record sprite sprite_y sprite_tile sprite_attr sprite_x ; a sprite of the OAM copy, by its byte offset (4 per sprite)
# What an enemy slot holds (enemy_initializers and enemy_runners, by kind).
# $00 is left unnamed: it is the koopa a green paratroopa becomes when
# stomped (check_stun_enemy), but also what a cleared slot holds. $01 is the
# koopa a red paratroopa becomes, which walks off ledges ($03 turns at them).
enum enemy_kind red_koopa_off_ledges=$01 buzzy_beetle=$02 red_koopa=$03 hammer_bro=$05 goomba=$06 blooper=$07 bullet=$08 cheep_cheep_slow=$0a cheep_cheep_fast=$0b podoboo=$0c piranha=$0d bouncing_paratroopa=$0e red_paratroopa=$0f flying_paratroopa=$10 lakitu=$11 spiny=$12 flying_cheep_cheeps=$14 bowser_flame=$15 fireworks=$16 bullets_and_cheep_cheeps=$17 end_frenzy=$18 firebar_slow=$1b firebar_fast=$1c firebar_slow_reverse=$1d firebar_fast_reverse=$1e long_firebar=$1f balance_platform=$24 vertical_platform=$25 lift_up=$26 lift_down=$27 side_platform=$28 drop_platform=$29 right_platform=$2a small_lift_up=$2b small_lift_down=$2c bowser=$2d powerup=$2e vine=$2f flagpole_flag=$30 star_flag=$31 spring=$32 bullet_cannon=$33 warp_zone=$34 retainer=$35

