io $4000 apu_pulse1_control    ; duty, length halt, envelope
io $4001 apu_pulse1_sweep
io $4002 apu_pulse1_period_low
io $4003 apu_pulse1_period_high ; and length; restarts the note
io $4004 apu_pulse2_control
io $4005 apu_pulse2_sweep
io $4006 apu_pulse2_period_low
io $4007 apu_pulse2_period_high
