io $4010 apu_dmc_control
io $4011 apu_dmc_level
io $4012 apu_dmc_address
io $4013 apu_dmc_length
io $4014 oam_dma
io $4015 apu_status            ; channel enables
io $4016 joypad_ports 2
io $4016 joypad1_port
io $4017 apu_frame_counter     ; written: sequencer mode and reset; read: joypad 2

